import express from 'express';
import { z } from 'zod';

const MenuBaru = z.object({
  nama: z.string({ error: 'nama wajib berupa teks' }).min(2, 'nama minimal 2 huruf'),
  harga: z.number({ error: 'harga wajib berupa angka' }).int().positive('harga harus lebih dari 0'),
  kategori: z.enum(['minuman', 'makanan']).default('minuman'),
});
const app = express();
app.use(express.json());
app.post('/menu', (req, res) => {
  const hasil = MenuBaru.safeParse(req.body);
  if (!hasil.success) {
    return res.status(400).json({ error: hasil.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`) });
  }
  res.status(201).json(hasil.data);
});
const server = app.listen(3000);

const kirim = async (body) => {
  const r = await fetch('http://localhost:3000/menu', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  console.log(r.status, await r.json());
};
await kirim({ nama: 'Es Teh', harga: 8000, gratis: true });
await kirim({ nama: 'K', harga: -1 });
await kirim({ harga: '8000' });
server.close();

